import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CeZVUxyP.js";const u=JSON.parse('{"title":"REA: investigating how games work","description":"","frontmatter":{},"headers":[],"relativePath":"research/rea.md","filePath":"research/rea.md","lastUpdated":1794254893000}'),r={name:"research/rea.md"};function n(s,e,l,d,p,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="rea-investigating-how-games-work" tabindex="-1">REA: investigating how games work <a class="header-anchor" href="#rea-investigating-how-games-work" aria-label="Permalink to &quot;REA: investigating how games work&quot;">​</a></h1><p><strong>Reviewed:</strong> 2026-11-09 · <strong>CLI tested:</strong> rea-agents 6.8.0 · <strong>Status:</strong> Initial static inspection completed; gameplay analysis remains untested.</p><p><a href="https://github.com/morluto/rea" target="_blank" rel="noreferrer">REA on GitHub</a> is an agent-facing reverse-engineering toolkit. Its CLI and MCP interface connect analysis workflows to an AI assistant. It is useful for investigating existing software; it does not generate a complete game or recover an original source repository automatically. Native disassembly and pseudocode workflows require a supported analysis provider, such as Hopper, Ghidra, IDA, or Kuna. <a href="https://github.com/morluto/rea#readme" target="_blank" rel="noreferrer">Project overview</a></p><h2 id="why-investigate-it-for-our-game" tabindex="-1">Why investigate it for our game? <a class="header-anchor" href="#why-investigate-it-for-our-game" aria-label="Permalink to &quot;Why investigate it for our game?&quot;">​</a></h2><p>Our proposed use is to study a narrowly defined behavior, write down what the evidence supports, and build an independent implementation for our own prototype.</p><table tabindex="0"><thead><tr><th>Research track</th><th>Proposed question</th><th>Useful outcome</th></tr></thead><tbody><tr><td>Programming</td><td>How does a small interaction change state?</td><td>A state diagram and tests for our own implementation</td></tr><tr><td>Audio</td><td>How does a positional sound calculation behave?</td><td>A measured formula and a listening test</td></tr><tr><td>3D integration</td><td>Which runtime and asset containers are actually present?</td><td>A map of the asset pipeline and its unknowns</td></tr><tr><td>Reliability</td><td>Can an agent distinguish evidence from guesses?</td><td>A reproducible investigation with explicit limits</td></tr></tbody></table><p>These are proposed experiments, not demonstrated capabilities on our target games.</p><h2 id="start-with-an-installation-inventory" tabindex="-1">Start with an installation inventory <a class="header-anchor" href="#start-with-an-installation-inventory" aria-label="Permalink to &quot;Start with an installation inventory&quot;">​</a></h2><p>REA&#39;s <code>inspect-desktop-application</code> command inventories a selected directory and inspects bounded headers and metadata. It does not launch the target or modify it. It can suggest runtime families and follow-up probes, but those candidates do not prove that a component executes. A directory inventory is not archive extraction or decompilation. <a href="https://github.com/morluto/rea/blob/main/docs/desktop-applications.md" target="_blank" rel="noreferrer">Desktop inspection guide</a></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rea</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect-desktop-application</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /absolute/path/to/game</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>Save the output outside the game installation. Review coverage and limitations before interpreting results. An empty candidate list alone does not prove that a game is absent or identify its engine.</p><h2 id="local-feasibility-test" tabindex="-1">Local feasibility test <a class="header-anchor" href="#local-feasibility-test" aria-label="Permalink to &quot;Local feasibility test&quot;">​</a></h2><p>A first test used REA 6.8.0 on macOS with Node 22.23.4. The selected Steam game directory contained leftover logs rather than a game executable. The operation returned an inventory, with no runtime candidate or follow-up binary probe. This establishes that the inventory workflow runs locally; it does <strong>not</strong> establish successful analysis of a game&#39;s implementation.</p><p>The CLI also inventoried a launcher shortcut and a separate user-data directory. Raw reports remain local. Personal save names, profile paths, logs, screenshots, and save contents are not part of this public page.</p><p><strong>Result:</strong> Installation discovery works for this narrow test. Native game analysis is blocked until a complete installation or a suitable executable is available.</p><h2 id="a-bounded-next-experiment" tabindex="-1">A bounded next experiment <a class="header-anchor" href="#a-bounded-next-experiment" aria-label="Permalink to &quot;A bounded next experiment&quot;">​</a></h2><ol><li>Select a complete installation and one concrete behavior to investigate.</li><li>Inventory the directory and identify the actual executable.</li><li>Check provider compatibility with that executable format and architecture.</li><li>Collect the smallest relevant evidence set and preserve its limitations.</li><li>Implement a small original analogue in our prototype.</li><li>Compare behavior with explicit tests and record human effort.</li></ol><p>For a first gameplay study, a small open-source sample game would let us compare inferred behavior against known source code. That gives us a way to measure the agent&#39;s accuracy before tackling a large commercial title.</p><h2 id="setup-and-limits" tabindex="-1">Setup and limits <a class="header-anchor" href="#setup-and-limits" aria-label="Permalink to &quot;Setup and limits&quot;">​</a></h2><p>The tested package requires a newer Node runtime than the machine&#39;s existing Node 22.22.2. This trial used a separate npm-provided Node 22.23.4 runtime and did not register a persistent MCP server. Future runs should record the exact package and provider versions. Consult the current <a href="https://github.com/morluto/rea#what-you-can-analyze" target="_blank" rel="noreferrer">installation requirements</a> before setup.</p><p>CLI results can be saved and inspected later through REA&#39;s evidence workflows. Separate command invocations are separate processes; preserve reports when you need continuity. <a href="https://github.com/morluto/rea/blob/main/docs/getting-started/cli.md" target="_blank" rel="noreferrer">CLI and evidence guide</a></p><p>Use the <a href="./../experiments/template.html">experiment template</a> to record the hypothesis, inputs, evidence, failure cases, and conclusion. Do not treat filenames, model guesses, or a plausible-looking pseudocode listing as proof of gameplay behavior.</p>',22)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
